.lp-legal{width:min(760px,calc(100% - 32px));margin-inline:auto;padding-block:32px 48px}
.lp-legal-back{display:inline-flex;align-items:center;gap:6px;color:var(--accent);font-size:14px;text-decoration:none;margin-bottom:16px}
.lp-legal h1{font-size:28px;line-height:40px;margin:0 0 8px}
.lp-legal>p{color:var(--ink2);font-size:15px;line-height:28px;margin:0 0 20px}
.lp-legal-card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:20px;margin-bottom:16px}
.lp-legal-card h2{font-size:18px;line-height:28px;margin:0 0 8px}
.lp-legal-card p,.lp-legal-card li{color:var(--ink2);font-size:15px;line-height:28px;margin:0}
.lp-legal-card ul,.lp-legal-card ol{margin:0;padding-inline-start:20px}
.lp-legal-rows{display:grid;gap:12px;margin:0}
.lp-legal-rows div{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 12px;padding-bottom:12px;border-bottom:1px solid var(--line)}
.lp-legal-rows div:last-child{border-bottom:0;padding-bottom:0}
.lp-legal-rows dt{color:var(--muted);font-size:14px}
.lp-legal-rows dd{margin:0;font-size:15px;color:var(--ink)}
.lp-legal-rows a{color:var(--accent);text-decoration:none;direction:ltr;unicode-bidi:isolate}
.lp-footer-legal{display:flex;flex-wrap:wrap;gap:8px 16px;margin-top:12px}
.lp-footer-legal a{color:var(--ink2);font-size:14px;text-decoration:none}
.lp-footer-pages{display:flex;flex-wrap:wrap;gap:8px 16px;margin-top:12px}
.lp-footer-pages a{color:var(--ink2);font-size:14px;text-decoration:none}
.lp-footer-legal .lp-enamad{display:inline-flex;background:#fff;border-radius:12px;padding:4px}
.lp-footer-legal .lp-enamad img{width:72px;height:auto;display:block}
.lp-footer-legal .lp-bitpay{display:inline-flex;background:#fff;border-radius:12px;padding:4px}
.lp-footer-legal .lp-bitpay img{width:72px;height:auto;display:block}
.lp-footer-legal .lp-bitpay:not(.is-loaded){background:transparent;padding:0}
.lp-footer-legal .lp-bitpay:not(.is-loaded) img{width:1px;height:1px;opacity:0}
.lp-footer-legal .lp-enamad:not(.is-loaded){background:transparent;padding:0}
.lp-footer-legal .lp-enamad:not(.is-loaded) img{width:1px;height:1px;opacity:0}

